package org.salahguard.app
import org.json.*
import org.junit.Assert.*
import org.junit.Test
class CollectibleRulesTest {
 private fun cards():List<JSONObject> = CollectibleRules.rarities.flatMapIndexed{r,rarity->(0..2).map{i->JSONObject().put("id","00000000-0000-0000-0000-"+(r*3+i).toString().padStart(12,'0')).put("title","Synthetic fixture").put("story","Synthetic fixture, no historical claim.").put("rarity",rarity).put("verification","verified").put("status","published").put("artId","11111111-1111-1111-1111-111111111111").put("artVerified",true).put("edition",2).put("englishReviewed",true).put("urduReviewed",true).put("english","Synthetic test story, no religious claim.").put("urdu","یہ صرف جانچ کے لیے ایک آزمائشی کہانی ہے۔").put("references",JSONArray().put(JSONObject().put("title","Fixture only").put("url","https://example.invalid")))}}
 @Test fun exactRarityBoundariesAndDistinctCards(){for((roll,rarity) in listOf(1 to "common",55 to "common",56 to "uncommon",85 to "uncommon",86 to "rare",97 to "rare",98 to "ultra",100 to "ultra")){var calls=0;val selected=CollectibleRules.select(cards()){_,_->if(calls++%2==0)roll else 0};assertEquals(3,selected.map{it.getString("id")}.distinct().size);assertTrue(selected.all{it.getString("rarity")==rarity})}}
 @Test fun ownershipCommitsBeforeAnimationAndRetry(){val root=JSONObject().put("records",JSONArray()).put("economy",JSONObject().put("balance",1000).put("claims",JSONObject()).put("transactions",JSONObject()));CollectibleRules.cacheLibrary(root,JSONArray(cards()));val id="12345678-1234-1234-1234-123456789abc";CollectibleRules.purchase(root,id,draw={min,_->min});val restored=JSONObject(root.toString());CollectibleRules.purchase(restored,id);assertEquals(500,restored.getJSONObject("economy").getInt("balance"));val copies=restored.getJSONObject("collectibles").getJSONObject("copies");assertEquals(3,copies.length());val copy=copies.keys().next();assertFalse(copies.getJSONObject(copy).getBoolean("revealed"));CollectibleRules.reveal(restored,copy);CollectibleRules.reveal(restored,copy);assertTrue(copies.getJSONObject(copy).getBoolean("revealed"))}
 @Test fun incompleteLibraryDoesNotSpend(){val root=JSONObject().put("records",JSONArray()).put("economy",JSONObject().put("balance",1000).put("claims",JSONObject()).put("transactions",JSONObject()));assertTrue(runCatching{CollectibleRules.purchase(root,"12345678-1234-1234-1234-123456789abc")}.isFailure);assertEquals(1000,root.getJSONObject("economy").getInt("balance"))}
}
